defmodule Pluteus.Repo.Migrations.CreateAcquisitions do
  use Ecto.Migration

  @states ~w(recorded stored identified placed vanished)
  @essences ~w(lossy lossless unknown not_applicable)
  @media_classes ~w(companion audio video image text)
  @stages ~w(acquire identify place normalize analyse)

  def change do
    # spec-04 §4.2. The custody-layer record holding a file between arriving and
    # being placed, and keeping what placement concluded from afterwards. Its
    # identifier is the one the placed asset takes, so it is minted here and
    # never generated by the database.
    create table(:acquisitions, primary_key: false) do
      add :id, :uuid, primary_key: true
      add :inbox_path, :text, null: false
      add :inbox_directory, :text, null: false
      add :location, :text, null: false
      add :state, :string, null: false

      # Set once the inbox no longer holds the file for this record: renamed out
      # of it, removed after a verified copy, or found gone.
      add :inbox_released_at, :utc_datetime_usec

      add :size, :bigint
      add :digest, :text
      add :digest_algorithm, :string

      add :format, :string
      add :probe, :map
      add :streams, {:array, :map}
      add :essence, :string
      add :media_class, :string
      add :companion_kind, :string

      add :digital_item_id, references(:digital_items, type: :uuid, on_delete: :nothing)

      timestamps(type: :utc_datetime_usec)
    end

    create unique_index(:acquisitions, [:location])
    create index(:acquisitions, [:inbox_path, :digest])
    create index(:acquisitions, [:inbox_directory])
    create index(:acquisitions, [:state])

    # §4.3: at most one acquisition in progress holds an inbox path.
    create unique_index(:acquisitions, [:inbox_path],
             where: "inbox_released_at IS NULL",
             name: :acquisitions_one_in_progress_per_path_index
           )

    create constraint(:acquisitions, :state_must_be_known, check: in_list("state", @states))

    create constraint(:acquisitions, :essence_must_be_known,
             check: "essence IS NULL OR #{in_list("essence", @essences)}"
           )

    create constraint(:acquisitions, :media_class_must_be_known,
             check: "media_class IS NULL OR #{in_list("media_class", @media_classes)}"
           )

    create constraint(:acquisitions, :measured_once_stored,
             check:
               "state IN ('recorded', 'vanished') OR num_nulls(size, digest, digest_algorithm) = 0"
           )

    create constraint(:acquisitions, :identified_before_placed,
             check:
               "state NOT IN ('identified', 'placed') OR num_nulls(format, essence, media_class) = 0"
           )

    create constraint(:acquisitions, :placed_under_a_digital_item,
             check: "(state = 'placed') = (digital_item_id IS NOT NULL)"
           )

    create constraint(:acquisitions, :a_companion_names_its_kind,
             check: "(media_class = 'companion') = (companion_kind IS NOT NULL)"
           )

    # §4.1. What the inbox last looked like for each file not yet acquired. A
    # file is settled once the same size and modification time have been seen
    # for the settle interval.
    create table(:inbox_sightings, primary_key: false) do
      add :inbox_path, :text, primary_key: true
      add :size, :bigint, null: false
      add :mtime, :bigint, null: false
      add :seen_at, :utc_datetime_usec, null: false
    end

    # spec-04 §9. What a stage could not do, recorded against what it was
    # working on, for a person to see and clear.
    create table(:ingest_findings, primary_key: false) do
      add :id, :uuid, primary_key: true
      add :stage, :string, null: false
      add :kind, :string, null: false
      add :permanent, :boolean, null: false
      add :detail, :map, null: false, default: %{}

      add :acquisition_id, references(:acquisitions, type: :uuid, on_delete: :nothing)
      add :location, :text
      add :digital_item_id, references(:digital_items, type: :uuid, on_delete: :nothing)
      add :input_id, references(:res, type: :uuid, on_delete: :nothing)
      add :tool_version_id, references(:tool_versions, type: :uuid, on_delete: :nothing)

      add :recorded_at, :utc_datetime_usec, null: false
      add :cleared_at, :utc_datetime_usec
      add :cleared_by, references(:principals, type: :uuid, on_delete: :nothing)

      timestamps(type: :utc_datetime_usec)
    end

    create index(:ingest_findings, [:acquisition_id])
    create index(:ingest_findings, [:digital_item_id])
    create index(:ingest_findings, [:input_id, :tool_version_id])

    create constraint(:ingest_findings, :stage_must_be_known, check: in_list("stage", @stages))

    create constraint(:ingest_findings, :a_finding_has_a_subject,
             check: "num_nonnulls(acquisition_id, location, digital_item_id, input_id) >= 1"
           )

    create constraint(:ingest_findings, :an_analysis_finding_names_its_tool,
             check: "stage <> 'analyse' OR (input_id IS NOT NULL AND tool_version_id IS NOT NULL)"
           )

    create constraint(:ingest_findings, :clearing_is_attributed,
             check: "(cleared_at IS NULL) = (cleared_by IS NULL)"
           )

    # Stray bytes are recorded once, not again on every pass that finds them.
    create unique_index(:ingest_findings, [:location],
             where: "location IS NOT NULL AND cleared_at IS NULL",
             name: :ingest_findings_one_open_per_location_index
           )
  end

  defp in_list(column, values) do
    "#{column} IN (#{Enum.map_join(values, ", ", &"'#{&1}'")})"
  end
end
